#!/usr/bin/env python3
"""Compile deterministic static bundles; --check catches stale generated files."""
import argparse
import re
from pathlib import Path


def build(root: Path, *, check=False) -> int:
    source = root / 'socialctl/ui/assets'
    common = (source / 'tokens.css').read_text() + (source / 'components.css').read_text()
    targets = {
        'docs/style.css': 'web-layout.css',
        'socialctl/connection_service/assets/connection.css': 'connection-layout.css',
    }
    email = (source / 'otp.template.html').read_text()
    for name, value in re.findall(r'(--[a-z-]+):([^;]+);', (source / 'tokens.css').read_text()):
        email = email.replace('var(' + name + ')', value)
    bundles = {path: '/* Generated by scripts/build_ui_assets.py. Edit socialctl/ui/assets/. */\n' + common + (source / layout).read_text() for path, layout in targets.items()}
    bundles['deploy/auth/templates/otp.html'] = email
    bundles['socialctl/ui/email/otp.html'] = email
    stale = []
    for destination, expected in bundles.items():
        output = root / destination
        if not output.exists() or output.read_text() != expected:
            stale.append(destination)
            if not check:
                output.parent.mkdir(parents=True, exist_ok=True)
                output.write_text(expected)
    if check and stale:
        print('Stale UI assets: ' + ', '.join(stale))
        return 1
    return 0


if __name__ == '__main__':
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--root', type=Path, default=Path(__file__).resolve().parents[1])
    parser.add_argument('--check', action='store_true')
    args = parser.parse_args()
    raise SystemExit(build(args.root, check=args.check))
